Action: run_sql({'query': "WITH cuisine_est AS (\n  SELECT \n    e.gmap_id,\n    e.name,\n    e.avg_rating,\n    e.num_of_reviews,\n    e.price,\n    e.slchd_establishment_key,\n    CASE \n      WHEN LOWER(c.category) LIKE '%thai%' THEN 'Thai'\n      WHEN LOWER(c.category) LIKE '%korean%' THEN 'Korean'\n    END AS cuisine\n  FROM establishments e\n  JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\n  JOIN category c ON ec.category_id = c.category_id\n  WHERE LOWER(c.category) LIKE '%thai%' OR LOWER(c.category) LIKE '%korean%'\n)\nSELECT \n  cuisine,\n  COUNT(DISTINCT gmap_id) AS restaurant_count,\n  ROUND(AVG(avg_rating), 3) AS unweighted_avg_rating,\n  ROUND(SUM(avg_rating * num_of_reviews) / SUM(num_of_reviews), 3) AS review_weighted_avg_rating,\n  MIN(avg_rating) AS min_rating,\n  MAX(avg_rating) AS max_rating,\n  MEDIAN(avg_rating) AS median_rating,\n  SUM(num_of_reviews) AS total_reviews,\n  AVG(num_of_reviews) AS avg_reviews_per_rest\nFROM cuisine_est\nGROUP BY cuisine\nORDER BY unweighted_avg_rating DESC;"})

