Action: run_sql({'query': "SELECT e.gmap_id, e.name, e.slchd_establishment_key, c.category, i.inspection_id, v.violation_id, vc.critical\nFROM establishments e\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id\nLEFT JOIN inspections i ON e.slchd_establishment_key = i.slchd_establishment_key\nLEFT JOIN violations v ON i.inspection_id = v.inspection_id\nLEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nWHERE e.slchd_establishment_key IS NOT NULL\n  AND (LOWER(e.name) LIKE '%thai%' OR LOWER(e.name) LIKE '%korean%' OR LOWER(c.category) LIKE '%thai%' OR LOWER(c.category) LIKE '%korean%');"})

