Action: run_sql({'query': "WITH est_cuisine AS (\n  SELECT DISTINCT \n    e.gmap_id,\n    e.avg_rating,\n    e.num_of_reviews,\n    CASE \n      WHEN LOWER(c.category) LIKE '%korean%' THEN 'Korean'\n      WHEN LOWER(c.category) LIKE '%thai%' THEN 'Thai'\n    END AS cuisine\n  FROM establishments e\n  JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\n  JOIN category c ON ec.category_id = c.category_id\n  WHERE LOWER(c.category) LIKE '%thai%' OR LOWER(c.category) LIKE '%korean%'\n)\nSELECT \n  cuisine,\n  ROUND(AVG(avg_rating), 2) AS avg_rating,\n  ROUND(SUM(avg_rating * num_of_reviews) / SUM(num_of_reviews), 2) AS weighted_avg_rating,\n  COUNT(gmap_id) AS restaurant_count\nFROM est_cuisine\nGROUP BY cuisine\nORDER BY avg_rating DESC;"})

