Action: run_sql({'query': "WITH slchd_cuisine AS (\n  SELECT \n    ek.slchd_establishment_key,\n    CASE \n      WHEN LOWER(ek.name) LIKE '%korean%' OR LOWER(ek.name) LIKE '%cupbop%' THEN 'Korean'\n      WHEN LOWER(ek.name) LIKE '%thai%' THEN 'Thai'\n    END AS cuisine,\n    i.inspection_id,\n    v.violation_id,\n    vc.critical\n  FROM establishment_keys ek\n  JOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\n  LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n  LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n  WHERE LOWER(ek.name) LIKE '%thai%' OR LOWER(ek.name) LIKE '%korean%' OR LOWER(ek.name) LIKE '%cupbop%'\n)\nSELECT \n  cuisine,\n  COUNT(DISTINCT slchd_establishment_key) AS matched_restaurants,\n  COUNT(DISTINCT inspection_id) AS total_inspections,\n  COUNT(violation_id) AS total_violations,\n  SUM(CASE WHEN critical THEN 1 ELSE 0 END) AS critical_violations,\n  SUM(CASE WHEN NOT critical THEN 1 ELSE 0 END) AS non_critical_violations,\n  ROUND(COUNT(violation_id)::DOUBLE / COUNT(DISTINCT inspection_id), 2) AS violations_per_inspection\nFROM slchd_cuisine\nGROUP BY cuisine\nORDER BY total_violations DESC;"})

